            source2: 'Al Jazeera',
            sourceUrl2: 'https://www.aljazeera.com/sports/2026/7/1/kane-double-fires-england-to-comeback-win-over-dr-congo-at-world-cup-2026',
            sourceSnippet2: 'Kane double fires England to comeback win over DR Congo at World Cup 2026 — Al Jazeera',
            source3: 'ESPN',
